// =====================================================================
// Edge Function: announce-email
// Emails a posted announcement to the addressed board members through
// the verified society domain through the Resend HTTPS API.
//
// Secrets (Edge Functions → Secrets):
//   SMTP_PASS or RESEND_API_KEY – the Resend API key
//   SMTP_FROM – the verified sender address (default hello@usjlps.org)
//   PORTAL_URL / ALLOWED_ORIGINS – already set for admin-users
//
// Only the President, Vice President and Faculty Advisor may send, and
// each announcement can be emailed only once (recorded in activity_log).
// =====================================================================
import { createClient } from 'npm:@supabase/supabase-js@2'

const SUPABASE_URL = Deno.env.get('SUPABASE_URL')!
const ANON_KEY = Deno.env.get('SUPABASE_ANON_KEY')!
const SERVICE_ROLE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
const RESEND_API_KEY = (Deno.env.get('RESEND_API_KEY') || Deno.env.get('SMTP_PASS') || '').trim()
const SMTP_FROM = (Deno.env.get('SMTP_FROM') || 'hello@usjlps.org').trim()
// Resend HTTPS transport. Secrets stay server-side. No SMTP connection is used.
type MailAddress = string | { name?: string; address: string }
type InlineAttachment = { filename: string; content: Uint8Array | string; cid?: string; contentType?: string }
type MailMessage = {
  from: MailAddress; to: MailAddress | MailAddress[]; subject: string; html: string; text?: string
  replyTo?: MailAddress; attachments?: InlineAttachment[]
}
class ResendSendError extends Error {
  constructor(public status: number, public userMessage: string) { super(userMessage); this.name = 'ResendSendError' }
}
function mailAddress(value: MailAddress): string {
  if (typeof value === 'string') return value
  const address = String(value.address).trim()
  if (/[\r\n<>]/.test(address)) throw new ResendSendError(422, 'The recipient email address is invalid.')
  const name = String(value.name || '').replace(/[\r\n]/g, ' ').replace(/[\\"]/g, '\\$&')
  return name ? `"${name}" <${address}>` : address
}
function base64Bytes(bytes: Uint8Array): string {
  let text = ''
  for (let offset = 0; offset < bytes.length; offset += 8192) {
    text += String.fromCharCode(...bytes.subarray(offset, offset + 8192))
  }
  return btoa(text)
}
function fatalMailError(error: unknown): boolean {
  return error instanceof ResendSendError && [400, 401, 403, 404, 422].includes(error.status)
}
function mailFailure(error: unknown): string {
  return error instanceof ResendSendError ? error.userMessage : 'Could not send the email. Please try again.'
}
const mailSleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms))
let nextMailAt = 0
let mailSlot: Promise<void> = Promise.resolve()
async function waitForMailSlot(): Promise<void> {
  const slot = mailSlot.then(async () => {
    const pause = Math.max(0, nextMailAt - Date.now())
    if (pause) await mailSleep(pause)
    nextMailAt = Date.now() + 550
  })
  mailSlot = slot.catch(() => {})
  await slot
}
async function sendResendMail(message: MailMessage): Promise<{ messageId: string }> {
  if (!RESEND_API_KEY) throw new ResendSendError(401, 'Email is not configured. Save your Resend API key in SMTP_PASS or RESEND_API_KEY.')
  const recipients = Array.isArray(message.to) ? message.to : [message.to]
  const payload = {
    from: mailAddress(message.from), to: recipients.map(mailAddress), subject: message.subject,
    html: message.html, ...(message.text ? { text: message.text } : {}),
    ...(message.replyTo ? { reply_to: mailAddress(message.replyTo) } : {}),
    ...(message.attachments?.length ? { attachments: message.attachments.map((item) => ({
      filename: item.filename,
      content: typeof item.content === 'string' ? item.content : base64Bytes(item.content),
      ...(item.cid ? { content_id: item.cid } : {}),
      ...(item.contentType ? { content_type: item.contentType } : {}),
    })) } : {}),
  }
  // Keep one idempotency key across retries so a temporary provider error cannot duplicate a message.
  const idempotencyKey = `lps-mail-${crypto.randomUUID()}`
  for (let attempt = 0; attempt < 3; attempt++) {
    await waitForMailSlot()
    let response: Response
    try {
      response = await fetch('https://api.resend.com/emails', {
        method: 'POST', signal: AbortSignal.timeout(15000),
        headers: { Authorization: `Bearer ${RESEND_API_KEY}`, 'Content-Type': 'application/json', 'Idempotency-Key': idempotencyKey },
        body: JSON.stringify(payload),
      })
    } catch (error) {
      const timeout = error instanceof Error && /timeout|abort/i.test(error.name)
      throw new ResendSendError(503, timeout ? 'Resend did not respond in time. Please try again in a minute.' : 'Could not reach Resend. Please try again in a minute.')
    }
    const data = (await response.json().catch(() => ({}))) || {}
    if (response.ok && typeof data.id === 'string') return { messageId: data.id }
    if ((response.status === 429 || response.status >= 500) && attempt < 2) {
      const header = Number(response.headers.get('retry-after'))
      await mailSleep(Number.isFinite(header) && header > 0 ? Math.min(header, 10) * 1000 : (attempt + 1) * 1200)
      continue
    }
    // Only provider status/name/message are logged, never request headers or API keys.
    console.error('Resend email failed', { status: response.status, name: String(data.name || ''), message: String(data.message || '').slice(0, 300) })
    const reason = response.status === 401 ? 'Resend rejected the API key. Check SMTP_PASS or RESEND_API_KEY.'
      : response.status === 403 ? 'Resend refused this sender. Check the verified domain and API key sending permissions.'
      : response.status === 429 ? 'The email service is busy. Please wait a minute and try again.'
      : response.status === 400 || response.status === 422 ? 'Resend rejected the email details. Check the sender and recipient addresses; see the function Logs for details.'
      : 'Resend could not send the email. Please try again later.'
    throw new ResendSendError(response.status, reason)
  }
  throw new ResendSendError(503, 'Resend could not send the email. Please try again later.')
}

// Embedded society logo: no remote-image download is needed by the recipient.
const SOCIETY_LOGO_BASE64 = ''
function embeddedLogo(): Uint8Array { return Uint8Array.from(atob(SOCIETY_LOGO_BASE64), (c) => c.charCodeAt(0)) }
const LOGO_URL = 'cid:society-logo'
const PORTAL_URL = (Deno.env.get('PORTAL_URL') || 'http://localhost:5173').trim().replace(/\/+$/, '')
const ALLOWED_ORIGINS = (Deno.env.get('ALLOWED_ORIGINS') || PORTAL_URL).split(',').map((s) => s.trim().replace(/\/+$/, '')).filter(Boolean)
const SENDERS = ['president', 'vice_president', 'faculty_advisor']
const ROLE_LABEL: Record<string, string> = {
  president: 'President', vice_president: 'Vice President', treasurer: 'Treasurer', secretary: 'Secretary',
  events_chair: 'Events & Outreach', marketing_chair: 'Marketing & Social Media', faculty_advisor: 'Faculty Advisor', campus_activities: 'Campus Activities',
}

function cors(origin: string | null, requested: string | null) {
  const allow = origin && ALLOWED_ORIGINS.includes(origin) ? origin : ALLOWED_ORIGINS[0]
  return {
    'Access-Control-Allow-Origin': allow,
    'Access-Control-Allow-Headers': requested || 'authorization, x-client-info, apikey, content-type',
    'Access-Control-Allow-Methods': 'POST, OPTIONS',
    Vary: 'Origin',
  }
}
class HttpError extends Error { constructor(public status: number, message: string) { super(message) } }

// EMAIL_IMAGE_CORE_START
// This pure core is copied verbatim (without exports) into the two standalone
// Edge Functions. Keep in sync; email-images.test.cjs checks all three copies.
interface EmailImage {
  id: string
  path: string
  alt: string
  width: 160 | 320 | 512
}
const EMAIL_IMAGE_BUCKET = 'announcement-images'
const MAX_EMAIL_IMAGES = 6
const MAX_EMAIL_IMAGE_BYTES = 1_048_576
const imageUuid = '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}'
const imagePath = new RegExp(`^${imageUuid}/${imageUuid}\\.(png|jpg)$`)
const imageId = new RegExp(`^${imageUuid}$`)
const imageMarker = (id: string) => `[[image:${id}]]`

function validateEmailImages(value: unknown): EmailImage[] {
  if (value === undefined || value === null) return []
  if (!Array.isArray(value) || value.length > MAX_EMAIL_IMAGES) throw new Error('Use up to 6 email images.')
  const ids = new Set<string>()
  return value.map((v: unknown) => {
    if (!v || typeof v !== 'object') throw new Error('Invalid email image.')
    const o = v as Record<string, unknown>
    if (typeof o.id !== 'string' || !imageId.test(o.id) || ids.has(o.id)
      || typeof o.path !== 'string' || !imagePath.test(o.path)
      || typeof o.alt !== 'string' || o.alt.length > 180
      || ![160, 320, 512].includes(Number(o.width)) || typeof o.width !== 'number') {
      throw new Error('Invalid email image. Upload the file again.')
    }
    ids.add(o.id)
    return { id: o.id, path: o.path, alt: o.alt, width: o.width as EmailImage['width'] }
  })
}

type EmailBodyPart = { text: string } | { image: EmailImage }
function emailBodyParts(body: string, value?: unknown): EmailBodyPart[] {
  const images = validateEmailImages(value)
  const byId = new Map(images.map(i => [i.id, i]))
  const pattern = new RegExp(`\\[\\[image:(${imageUuid})\\]\\]`, 'g')
  const parts: EmailBodyPart[] = []
  let cursor = 0
  for (const match of body.matchAll(pattern)) {
    if (match.index! > cursor) parts.push({ text: body.slice(cursor, match.index) })
    const image = byId.get(match[1])
    parts.push(image ? { image } : { text: '[Image unavailable]' })
    cursor = match.index! + match[0].length
  }
  if (cursor < body.length) parts.push({ text: body.slice(cursor) })
  return parts
}
const imageEscape = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
function emailBodyHtml(body: string, images: unknown, src: (image: EmailImage) => string, links = false): string {
  return emailBodyParts(body, images).map(part => {
    if ('image' in part) {
      const i = part.image
      return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:18px 0;table-layout:fixed;width:100%;"><tr><td align="center"><img src="${imageEscape(src(i))}" alt="${imageEscape(i.alt)}" width="${i.width}" style="display:block;width:${i.width}px;max-width:100%;height:auto;border:0;margin:0 auto;"></td></tr></table>`
    }
    return part.text.trim().split(/\n\s*\n/).filter(Boolean).map(para => {
      let text = imageEscape(para).replace(/\r?\n/g, '<br>')
      if (links) text = text.replace(/https?:\/\/[^\s<]+/g, url => `<a href="${url}" style="color:#123F31;">${url}</a>`)
      return `<p style="margin:0 0 16px;font-size:16px;line-height:1.65;overflow-wrap:anywhere;">${text}</p>`
    }).join('')
  }).join('')
}
function emailBodyText(body: string, images?: unknown): string {
  return emailBodyParts(body, images).map(p => 'text' in p ? p.text : `\n[Image: ${p.image.alt || 'Announcement image'}]\n`).join('')
}
// EMAIL_IMAGE_CORE_END
// Load only validated paths from our own bucket: no arbitrary URLs / SSRF.
async function announcementImageAttachments(admin: ReturnType<typeof createClient>, body: string, value: unknown): Promise<InlineAttachment[]> {
  let images: EmailImage[]
  try { images = validateEmailImages(value) } catch { throw new HttpError(400, 'Invalid announcement images. Remove and upload them again.') }
  const referenced = images.filter(i => body.includes(imageMarker(i.id)))
  const files: InlineAttachment[] = []
  for (const image of referenced) {
    const { data, error } = await admin.storage.from(EMAIL_IMAGE_BUCKET).download(image.path)
    if (error || !data || data.size > MAX_EMAIL_IMAGE_BYTES) throw new HttpError(400, 'An email image is missing or too large. No emails were sent. Remove it and upload it again.')
    const content = new Uint8Array(await data.arrayBuffer())
    const png = image.path.endsWith('.png')
    const signatureOK = png
      ? [137,80,78,71,13,10,26,10].every((b, n) => content[n] === b)
      : content[0] === 255 && content[1] === 216 && content[2] === 255
    if (!signatureOK) throw new HttpError(400, 'An email image is not a supported PNG or JPEG. No emails were sent.')
    files.push({ filename: `image-${image.id}.${png ? 'png' : 'jpg'}`, content, cid: `announcement-${image.id}`, contentType: png ? 'image/png' : 'image/jpeg' })
  }
  return files
}


const esc = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')

function emailHtml(a: Record<string, any>, name: string) {
  const pri = a.priority === 'urgent' ? ['URGENT', '#b3261e'] : a.priority === 'important' ? ['IMPORTANT', '#a87b00'] : null
  const audience = (a.audience ?? []).length ? (a.audience as string[]).map((r) => ROLE_LABEL[r] ?? r).join(', ') : 'Entire Executive Board'
  const body = emailBodyHtml(String(a.body), a.email_images, i => `cid:announcement-${i.id}`, true)
  const tags = (a.tags ?? []).map((t: string) => `<span style="display:inline-block;margin:0 6px 6px 0;padding:3px 9px;border:1px solid #e3dfd5;font-size:12px;color:#6f6c66;">#${esc(t)}</span>`).join('')
  const url = `${PORTAL_URL}/announcements`
  return `<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>@media screen and (max-width:480px){.email-content{padding-left:20px!important;padding-right:20px!important}.email-brand{font-size:19px!important;letter-spacing:2px!important;overflow-wrap:anywhere!important}}</style></head>
<body style="margin:0;padding:0;background:#f4f2ec;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f4f2ec;"><tr><td align="center" style="padding:32px 12px;">
<table class="email-frame" role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:600px;table-layout:fixed;overflow-wrap:anywhere;background:#ffffff;border:1px solid #e3dfd5;">
<tr><td align="center" style="background:#0b0b0b;padding:30px 24px 26px;border-bottom:4px solid #C9A54C;">
  <img src="${LOGO_URL}" width="76" height="76" alt="USJ Leadership & Professional Society" style="display:block;border:0;width:76px;height:76px;border-radius:50%;margin:0 auto 14px;">
  <div class="email-brand" style="font-family:Georgia,'Times New Roman',serif;font-size:26px;letter-spacing:4px;color:#ffffff;">USJ E-BOARD</div>
  <div style="font-family:Arial,Helvetica,sans-serif;font-size:11px;letter-spacing:3px;color:#C9A54C;margin-top:6px;">NEW ANNOUNCEMENT</div>
</td></tr>
<tr><td class="email-content" style="padding:36px 44px 8px;font-family:Arial,Helvetica,sans-serif;color:#1d1d1d;">
  ${pri ? `<div style="display:inline-block;margin:0 0 14px;padding:4px 10px;background:${pri[1]};color:#fff;font-size:11px;font-weight:bold;letter-spacing:2px;">${pri[0]}</div>` : ''}
  <div style="font-family:Georgia,'Times New Roman',serif;font-size:24px;line-height:1.3;color:#0b0b0b;margin:0 0 8px;">${esc(String(a.title))}</div>
  <div style="font-size:13px;color:#6f6c66;margin:0 0 22px;">From ${esc(a.author_name || 'the Executive Board')}${a.author_position ? ` &middot; ${esc(a.author_position)}` : ''} &nbsp;|&nbsp; To: ${esc(audience)}</div>
  <p style="font-size:16px;line-height:1.6;margin:0 0 16px;">Dear ${esc(name)},</p>
  <div style="font-size:16px;line-height:1.6;margin:0 0 18px;">${body}</div>
  ${tags ? `<div style="margin:0 0 6px;">${tags}</div>` : ''}
</td></tr>
<tr><td align="center" style="padding:14px 44px 30px;">
  <table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr><td bgcolor="#123F31" style="background:#123F31;">
    <a href="${url}" style="display:inline-block;padding:15px 34px;font-family:Arial,Helvetica,sans-serif;font-size:14px;font-weight:bold;letter-spacing:2px;color:#ffffff;text-decoration:none;">OPEN IN PORTAL</a>
  </td></tr></table>
</td></tr>
<tr><td style="padding:0 44px;"><div style="border-top:1px solid #e3dfd5;font-size:0;line-height:0;">&nbsp;</div></td></tr>
<tr><td style="padding:22px 44px 34px;font-family:Arial,Helvetica,sans-serif;color:#6f6c66;font-size:13px;line-height:1.6;">
  <p style="margin:0;"><strong style="color:#1d1d1d;">Please do not reply to this message.</strong> This mailbox is not monitored. To respond, contact the author directly or use the portal.</p>
</td></tr>
<tr><td align="center" style="background:#0b0b0b;padding:18px 24px;font-family:Arial,Helvetica,sans-serif;font-size:11px;letter-spacing:1px;color:#a9a59c;">
  USJ Leadership & Professional Society &middot; University of Saint Joseph &middot; Executive Board Portal
</td></tr>
</table></td></tr></table></body></html>`
}

function emailText(a: Record<string, any>, name: string) {
  return `Dear ${name},\n\n${a.title}\n\n${emailBodyText(String(a.body), a.email_images)}\n\nFrom ${a.author_name || 'the Executive Board'}${a.author_position ? `, ${a.author_position}` : ''}\n\nOpen in the portal: ${PORTAL_URL}/announcements\n\nPlease do not reply to this message.`
}

Deno.serve(async (req) => {
  const headers = { ...cors(req.headers.get('origin'), req.headers.get('access-control-request-headers')), 'Content-Type': 'application/json' }
  if (req.method === 'OPTIONS') return new Response('ok', { headers })
  try {
    if (req.method !== 'POST') throw new HttpError(405, 'Method not allowed.')
    if (!RESEND_API_KEY) throw new HttpError(500, 'Email is not configured yet: save the Resend API key in SMTP_PASS or RESEND_API_KEY in Supabase → Edge Functions → Secrets.')
    const authHeader = req.headers.get('Authorization') || ''
    const userClient = createClient(SUPABASE_URL, ANON_KEY, { global: { headers: { Authorization: authHeader } } })
    const admin = createClient(SUPABASE_URL, SERVICE_ROLE_KEY, { auth: { persistSession: false } })

    const { data: { user } } = await userClient.auth.getUser()
    if (!user) throw new HttpError(401, 'Your session has expired. Please sign in again.')
    const { data: caller } = await admin.from('profiles').select('id, full_name, role, is_active').eq('auth_user_id', user.id).single()
    if (!caller?.is_active || !SENDERS.includes(caller.role)) throw new HttpError(403, 'Only the President, Vice President or Faculty Advisor can email announcements.')

    const { announcement_id } = await req.json().catch(() => ({}))
    if (typeof announcement_id !== 'string' || !/^[0-9a-f-]{36}$/i.test(announcement_id)) throw new HttpError(400, 'Invalid announcement.')
    const { data: a } = await admin.from('announcements').select('*').eq('id', announcement_id).single()
    if (!a) throw new HttpError(404, 'Announcement not found.')

    const { count: already } = await admin.from('activity_log').select('id', { count: 'exact', head: true })
      .eq('entity_type', 'announcement').eq('entity_id', a.id).eq('action', 'emailed')
    if (already) throw new HttpError(409, 'This announcement has already been emailed.')

    let q = admin.from('profiles').select('id, full_name, email, role').eq('is_active', true).not('email', 'is', null)
    if ((a.audience ?? []).length) q = q.in('role', a.audience)
    const { data: people } = await q
    const recipients = (people ?? []).filter((p) => p.id !== a.author_id && p.email)
    if (!recipients.length) return new Response(JSON.stringify({ sent: 0, failed: [] }), { headers })

    const imageFiles = await announcementImageAttachments(admin, a.body, a.email_images)
    const subject = `${a.priority === 'urgent' ? '[URGENT] ' : a.priority === 'important' ? '[Important] ' : ''}${a.title} — USJ E-Board`
    let sent = 0
    const failed: string[] = []
    for (const p of recipients) {
      const name = p.full_name || 'Board Member'
      try {
        await sendResendMail({ from: { name: 'USJ Leadership & Professional Society E-Board', address: SMTP_FROM }, to: p.email, subject, html: emailHtml(a, name), text: emailText(a, name), attachments: [{ filename: 'logo.png', content: embeddedLogo(), cid: 'society-logo', contentType: 'image/png' }, ...imageFiles] })
        sent++
      } catch (e) {
        console.error('send failed', p.email, e)
        failed.push(p.full_name || p.email)
        if (sent === 0 && fatalMailError(e)) {
          throw new HttpError(502, mailFailure(e))
        }
      }
    }

    await admin.from('activity_log').insert({
      actor_id: caller.id, actor_name: caller.full_name, action: 'emailed', entity_type: 'announcement',
      entity_id: a.id, entity_label: a.title, details: { sent, failed },
    })
    return new Response(JSON.stringify({ sent, failed }), { headers })
  } catch (e) {
    const status = e instanceof HttpError ? e.status : e instanceof ResendSendError ? 502 : 500
    const message = e instanceof HttpError ? e.message : mailFailure(e)
    if (!(e instanceof HttpError)) console.error(e)
    return new Response(JSON.stringify({ error: message }), { status, headers })
  }
})
